UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b170331-MFTLouTYKKdI.png', birthday = '1月21日', blood_type = 'AB', voice_actor = '上田麗奈', height = 156, description = '種族：ヒューマン・ピーチ　能力：<i>「クレイジー・シープ」</i>　所属：アンチデーモン軍団（第6部隊）' WHERE character_id = 'CH003933';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b174190-Yl9xcIc5VTtI.jpg', birthday = '9月10日', blood_type = 'AB', voice_actor = '羊宮妃那', height = 171, description = '職業：中学生（2年生）　山田アンナは物語のヒロインであり、市川京太郎の同級生で、恋の相手でもある。見た目は可愛いが、実はおっちょこちょいで、見た目とは裏腹にとても子供っぽい一面もある。  彼女は雑誌のモデルや女優としても活躍している。男女問わず大人気だが、不器用な一面もある。アンナは図書館で頻繁におやつを食べており、京太郎を困らせている。また、京太郎が他の誰かと関わると、執着に近いほどの嫉妬を見せることもある。' WHERE character_id = 'CH003934';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b174191-ZxpNhPXKgxhX.jpg', birthday = '3月26日', blood_type = 'B', voice_actor = '堀江瞬', height = NULL, description = '職業：中学生（2年生） Twitter：https://twitter.com/thanatos_moros  市川は、物語『僕の心のヤバイ奴』の主人公であり、山田アンナの同級生である。 漫画の冒頭では、陰気で人付き合いが苦手、サディスティックな少年として描かれ、クラスメートを殺したいとさえ思っているが、実のところ彼は、自己評価が極端に低く、ただ自分のそばにいるだけで周囲の人々が嫌悪感を抱いていると信じ込んでしまうほどだが、唯一その人を' WHERE character_id = 'CH003935';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b297344-O1WzfeRh5o8O.png', birthday = NULL, blood_type = NULL, voice_actor = '岡本信彦', height = NULL, description = NULL WHERE character_id = 'CH003936';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b306775-iAOV5fzymDbS.png', birthday = NULL, blood_type = NULL, voice_actor = '土屋李央', height = NULL, description = '彼女は、山田杏奈と同じ事務所に所属するモデルです。' WHERE character_id = 'CH003937';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b297346-JRFPFZaZxfzK.png', birthday = NULL, blood_type = NULL, voice_actor = '福島潤', height = NULL, description = NULL WHERE character_id = 'CH003938';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b306752-A10fEacTXiPl.png', birthday = NULL, blood_type = NULL, voice_actor = '皆口裕子', height = NULL, description = '山田さなえは、『僕の心のヤバイやつ』に登場する脇役である。彼女は山田優希の妻であり、山田杏奈の母親である。' WHERE character_id = 'CH003939';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b202927-bQP0mtgDeNt1.jpg', birthday = '5月15日', blood_type = NULL, voice_actor = '朝井彩加', height = NULL, description = 'アンナの親友。' WHERE character_id = 'CH003940';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b297345-jqx12kbZeAnc.png', birthday = NULL, blood_type = NULL, voice_actor = '佐藤元', height = NULL, description = NULL WHERE character_id = 'CH003941';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b207168-5yke9SeJWTCw.jpg', birthday = '10月23日', blood_type = NULL, voice_actor = '潘めぐみ', height = NULL, description = 'アンナの親しい友人のもう一人。アンナの交友関係の中で、最も陽気でエネルギッシュな人物だ。' WHERE character_id = 'CH003942';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b297347-m4n9BwniuLry.png', birthday = NULL, blood_type = NULL, voice_actor = '豊崎愛生', height = NULL, description = NULL WHERE character_id = 'CH003943';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b306756-gW1g1MeM1V8J.png', birthday = NULL, blood_type = NULL, voice_actor = '名塚佳織', height = NULL, description = '3年1組の担任の先生。元気いっぱいで活気あふれる先生で、よく動き回るのが好きです。' WHERE character_id = 'CH003944';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b193218-3mexVYcc0PoC.jpg', birthday = '11月9日', blood_type = NULL, voice_actor = '田村ゆかり', height = NULL, description = '京太郎の姉。' WHERE character_id = 'CH003945';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b306749-QVhr3FiPeobE.png', birthday = NULL, blood_type = NULL, voice_actor = '島﨑信長', height = NULL, description = '南条ハルヤは、『僕の心のヤバイ奴』に登場する脇役である。洗練されているが浅はかなプレイボーイである南条は、山田杏奈の容姿と社会的地位に惹かれる。彼は、市川京太郎にとっての常連の敵役であり、恋のライバルとして登場する。' WHERE character_id = 'CH003946';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b306758-dFbkLtS8Lafh.png', birthday = NULL, blood_type = NULL, voice_actor = '西村ちなみ', height = NULL, description = '彼女はカナと市川京太郎の母親である。一見、ごく普通の主婦のように見え、家事をこなし、家の掃除などもしているが、何らかのアルバイトもしているようだ。' WHERE character_id = 'CH003947';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b306774-USOM1phOJArx.png', birthday = NULL, blood_type = NULL, voice_actor = '井口裕香', height = NULL, description = 'カンナは、他人の恋愛事情に異常なほど関心を寄せることで知られている。彼女は3年生の時、3-1組で市川と山田の同級生となる。' WHERE character_id = 'CH003948';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b306773-7UCTL4Ct9mzc.png', birthday = NULL, blood_type = NULL, voice_actor = '細谷佳正', height = NULL, description = '山田優希は『僕の心のヤバイやつ』に登場する脇役である。彼は山田さなえの夫であり、副主人公である山田杏奈の父親でもある。物静かだが、娘を溺愛する父親で、料理やビデオゲームを楽しむのが好きだ。' WHERE character_id = 'CH003949';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b331161-7Hyz8k9BWNT7.png', birthday = NULL, blood_type = NULL, voice_actor = '梶裕貴', height = NULL, description = '市川と山田の頼もしい同級生。' WHERE character_id = 'CH003950';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b244631-brX66jFaOcex.jpg', birthday = '7月18日', blood_type = NULL, voice_actor = '種﨑敦美', height = NULL, description = NULL WHERE character_id = 'CH003951';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b306767-zpbM7Nb58ALS.png', birthday = NULL, blood_type = NULL, voice_actor = '中野裕斗', height = NULL, description = '彼はカナと市川京太郎の父親である。大学講師である。' WHERE character_id = 'CH003952';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b306761-GBxGGDZwIHx4.png', birthday = NULL, blood_type = NULL, voice_actor = '上田麗奈', height = NULL, description = 'ユリネは、のんびりとして物静かな若い女性だ。彼女は3年生の時、3年1組で市川と山田の同級生となる。' WHERE character_id = 'CH003953';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b306770-HN395EAbfe1z.png', birthday = NULL, blood_type = NULL, voice_actor = '斎賀みつき', height = NULL, description = '諏訪は山田のモデル担当マネージャーです。' WHERE character_id = 'CH003954';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b306755-EE48htaYlqeA.png', birthday = NULL, blood_type = NULL, voice_actor = '朝日奈丸佳', height = NULL, description = '南条の幼なじみ。関係を深めたいと思っているが、どうしても彼の目に留まることができないようだ。' WHERE character_id = 'CH003955';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b142801-OqKiluEFDfJp.png', birthday = '12月25日', blood_type = NULL, voice_actor = '佐倉綾音', height = 160, description = '北見北陵高校に通う、16歳のツバサの同級生。人気者でおしゃべりな女の子だ。 彼女は「ギャル」というサブカルチャーに傾倒しており、髪を金髪に染め、冬でもミニスカートを履き、携帯電話を操作できるようにと冬でも手袋をはめることを拒んでいる。ツバサに好意を抱いているようで、彼を恥ずかしがらせたり動揺させたりするために、彼にからかうことを楽しんでいる。（出典：ウィキペディア）' WHERE character_id = 'CH003956';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b148966-8ZRwipHnB7Kl.png', birthday = '9月23日', blood_type = NULL, voice_actor = '花守ゆみり', height = 157, description = 'ツバサとミナミの同級生で、漆黒の髪と控えめな性格、そして北海道弁を使わないという姿勢から、ミナミとは正反対の存在だ。 彼女はゲームが大好きだが、周囲に溶け込むためにファッション誌やメイク雑誌を読み、身だしなみにも気を遣っている。汗をかきやすい体質のため、さゆりはあらゆる運動を避けていたが、それがやがて人付き合いそのものを避けるようになる原因となった。友達がいないさゆりは、つばさと親近感を抱き、彼と友達になり、' WHERE character_id = 'CH003957';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b207989-NncMS5UmEbOn.jpg', birthday = '7月14日', blood_type = NULL, voice_actor = '上田麗奈', height = 150, description = 'ツバサの1学年上の先輩。フユキと同じような「ギャル」で、フユキは彼女をとても尊敬している。白がかった灰色のショートヘアをしている。特に勉強の面で非常に才能があると言われているが、実はとても内気で自信がない。（出典：ウィキペディア）' WHERE character_id = 'CH003958';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b142802-Enti0ea1Q8Tg.png', birthday = '4月4日', blood_type = NULL, voice_actor = '島﨑信長', height = 179, description = '彼は都会育ちの、かなりお調子者な男だ。本来なら口に出したくないようなことも、つい本音を漏らしてしまうことがある。寒さにはとても弱い。' WHERE character_id = 'CH003959';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323452-4mCvJe73wbwL.png', birthday = '1月1日', blood_type = NULL, voice_actor = '喜多村英梨', height = NULL, description = 'ミナミとモモコの母親。' WHERE character_id = 'CH003960';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b332569-oDykfpXkTMTb.png', birthday = NULL, blood_type = NULL, voice_actor = '河村梨恵', height = NULL, description = NULL WHERE character_id = 'CH003961';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323999-Z0qlIbuv1BcM.png', birthday = '10月2日', blood_type = NULL, voice_actor = '今泉葉子', height = 154, description = '四季翼のおばあちゃん。' WHERE character_id = 'CH003962';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b332570-HvXASRhDT1Lh.png', birthday = NULL, blood_type = NULL, voice_actor = '高塚正也', height = NULL, description = NULL WHERE character_id = 'CH003963';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b325013-YgJSaBprYaBX.png', birthday = NULL, blood_type = NULL, voice_actor = '田辺留依', height = NULL, description = NULL WHERE character_id = 'CH003964';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b220836-tt4WcUGQqGD9.png', birthday = NULL, blood_type = NULL, voice_actor = '久保ユリカ', height = NULL, description = '飛鳥の友人であり同級生で、自らを「ミナミの最大のファン」と称している。長い髪に大きなメガネをかけている。ミナミと同じ中学校に通っていたため、彼女がお気に入りのフィクションの登場人物に似ていることから、ミナミに夢中になっている。日菜はインターネット上でミナミをフォローし、ツバサを含め、ミナミに関するあらゆることを徹底的に調べ上げている。  （出典：ウィキペディア）' WHERE character_id = 'CH003965';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b220835-18iod5nhUl3y.jpg', birthday = NULL, blood_type = NULL, voice_actor = '永井真里子', height = NULL, description = 'さゆりの幼なじみで、彼女より1学年下の後輩。水泳部の部員で、運動神経が良く、ショートヘアで色黒だ。飛鳥は、さゆりと、彼女が翼に抱く恋心を、できる限り支えようとしている。（出典：ウィキペディア）' WHERE character_id = 'CH003966';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323450-Z7yFLy3fCL11.png', birthday = NULL, blood_type = NULL, voice_actor = '長江里加', height = NULL, description = NULL WHERE character_id = 'CH003967';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323451-s64G1x5wlvWf.png', birthday = '10月13日', blood_type = NULL, voice_actor = '松岡禎丞', height = 175, description = NULL WHERE character_id = 'CH003968';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b312403-0NwonEnqDhF0.png', birthday = '7月30日', blood_type = NULL, voice_actor = '長谷川育美', height = NULL, description = 'リシェは、20歳で亡くなり、5年前に婚約が破談になった瞬間に戻ってきた貴族の娘である。幾度もの転生を経て、彼女は数多くの技能と不屈の精神を身につけてきた。今回、7度目となるこの人生において、彼女はアーノルド皇太子と婚約している。' WHERE character_id = 'CH003969';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b312404-yF6cWJwnqft9.png', birthday = '12月28日', blood_type = NULL, voice_actor = '島﨑信長', height = NULL, description = 'ガルケインの皇太子。' WHERE character_id = 'CH003970';
