UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b317217-qdJ8jE1Wulzm.png', birthday = NULL, blood_type = NULL, voice_actor = '土岐隼一', height = NULL, description = '彼は怪我のため騎士になる道を断たれ、アーノルドに引き取られた。それ以来、彼はアーノルドの従者として仕えている。' WHERE character_id = 'CH003976';
