UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323315-KE6LiwaOmfE8.png', birthday = NULL, blood_type = NULL, voice_actor = '岡本信彦', height = NULL, description = NULL WHERE character_id = 'CH003983';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323872-iaqlNqyfcp68.png', birthday = NULL, blood_type = NULL, voice_actor = '大野智敬', height = NULL, description = NULL WHERE character_id = 'CH003984';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b208534-oBXb8vzSuzz5.png', birthday = NULL, blood_type = NULL, voice_actor = 'ファイルーズあい', height = NULL, description = 'RPG乙女ゲーム『ライトマジックとヒーロー』の隠し最終ボスとして転生した少女。当初は平穏な生活を送るつもりだったが、ダンジョンで初めて手に入れた魔法の力を駆使したことで「ゲーマー魂」に火がつき、あっという間にレベル上げに夢中になってしまった。  ユミエラは冷静沈着で論理的、そして無表情な性格であり、他者との関わりや、相手を理解し関係を築くことに苦手意識を抱いている。これに加え、漆黒の髪が' WHERE character_id = 'CH003985';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b313857-Z5cn7aQy51th.png', birthday = NULL, blood_type = NULL, voice_actor = '内田雄馬', height = NULL, description = 'パトリックは王立アカデミーの学生であり、ユミエラの親友である。辺境伯の次男で、戦闘戦術と風魔法に長けている。原作ゲーム『_光の魔法と英雄_』では、単なる脇役だった。  パトリックは誠実で心優しく、冷静沈着な性格で、ユミエラの奇行に対してよくツッコミ役を務める。彼女が「自分より強い人しか好きじゃない」と言って別の男性を断ったのを耳にして以来、彼は毎日レベルアップに励むようになった。' WHERE character_id = 'CH003986';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b208535-qloNESLDBxyW.jpg', birthday = NULL, blood_type = NULL, voice_actor = '和氣あず未', height = NULL, description = 'アリシアは、RPG乙女ゲーム『光の魔法と英雄』のヒロインです。彼女は珍しい光の魔法使いであり、そのおかげで平民でありながら王立アカデミーに入学することができました。  アリシアは、主人公らしい楽観的で明るい性格の持ち主だ。彼女は、自分の魔法を使って他の人を助けたいという思いから、王立アカデミーに入学した。' WHERE character_id = 'CH003987';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323732-NflvdUnpNo0M.png', birthday = NULL, blood_type = NULL, voice_actor = '前田弘喜', height = NULL, description = 'ロイヤル・アカデミーの前校長。国王の命令により、ロナルドに後任を譲った。' WHERE character_id = 'CH003988';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327837-VDOLLlfs1Nwb.png', birthday = NULL, blood_type = NULL, voice_actor = '長谷川育美', height = NULL, description = 'リタはユミエラのメイドです。' WHERE character_id = 'CH003989';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323733-2GGHhEeYmL19.png', birthday = NULL, blood_type = NULL, voice_actor = '古賀明', height = NULL, description = '黒髪という理由で娘のユミエラを疎遠にしていた父親。' WHERE character_id = 'CH003990';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327838-SeXxZzbYq8CX.png', birthday = NULL, blood_type = NULL, voice_actor = '古川慎', height = NULL, description = 'ロナルドは、王の命令により前任の校長に代わって着任した新しい校長である。前任者とは異なり、ロナルドはユミエラを支持しており、彼女と王との間の連絡役を務めている。' WHERE character_id = 'CH003991';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b372476-I35WTvx2EVl6.png', birthday = NULL, blood_type = NULL, voice_actor = '山下誠一郎', height = NULL, description = 'ライナスはレムレスト王国のスパイで、かつてユミエラを自分の王国へ移住させようとしたことがある。' WHERE character_id = 'CH003992';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b313858-sABb2fMOCsu3.png', birthday = NULL, blood_type = NULL, voice_actor = '八代拓', height = NULL, description = 'エドウィンは、この王国の第二王子であり、ゲーム『ライト・マジックと英雄』の主人公である。' WHERE character_id = 'CH003993';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323734-hiRxIr1RgHMe.png', birthday = NULL, blood_type = NULL, voice_actor = '柳田淳一', height = NULL, description = '王立アカデミーの剣術の指導者の一人。' WHERE character_id = 'CH003994';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327839-eqyu7Q2VCdBn.png', birthday = NULL, blood_type = NULL, voice_actor = '中原麻衣', height = NULL, description = 'その王国の女王であり、エドウィンの母である。夫と同様、彼女もユミエラに対してより敬意を払っている。' WHERE character_id = 'CH003995';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b372403-cM70ZsEvVqNh.jpg', birthday = NULL, blood_type = NULL, voice_actor = '柳田淳一', height = NULL, description = 'リューは、ユミエラが卵から育て上げたドラゴンです。' WHERE character_id = 'CH003996';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b372477-x6L6BXf13894.png', birthday = NULL, blood_type = NULL, voice_actor = '小野大輔', height = NULL, description = '魔王は、ゲーム『光の魔法と英雄』の最終ボスである。彼は闇の魔法を使い、かつては人間だった。' WHERE character_id = 'CH003997';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b313859-Mm4pGcub1MIz.png', birthday = NULL, blood_type = NULL, voice_actor = '石谷春貴', height = NULL, description = 'ウィリアムは、正義感が強く、短気な剣士だ。彼はゲーム『ライトマジックと英雄』に登場する3人の恋愛対象キャラクターの一人である。' WHERE character_id = 'CH003998';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327841-wtX9AAjOf0We.png', birthday = NULL, blood_type = NULL, voice_actor = '新垣樽助', height = NULL, description = 'この王国の統治者であり、エドウィンの父である。息子とは異なり、彼はユミエラをより支持しており、魔王との戦いを有利に進めるために彼女を利用しようとしている。' WHERE character_id = 'CH003999';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b372375-OSoc0bDzfrXS.png', birthday = NULL, blood_type = NULL, voice_actor = '稲垣好', height = NULL, description = '『ライトマジックと英雄』というゲームの中で、ジェシカはアリシアの親友だ。しかし、実際には二人は親しそうだとは見えない。ユミエラは、転生後にストーリーに干渉してしまった結果、自分自身がそうさせてしまったのではないかと疑っている。' WHERE character_id = 'CH004000';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b313860-nKlkmLII4HRh.png', birthday = NULL, blood_type = NULL, voice_actor = '天崎滉平', height = NULL, description = 'オズワルドは、ゲーム『ライト・マジックと英雄』に登場する3人の恋愛対象キャラクターのうちの1人です。彼は魔法に長けており、4つの基本属性すべての魔法を使うことができます。' WHERE character_id = 'CH004001';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323736-T190ddpr2Rin.png', birthday = NULL, blood_type = NULL, voice_actor = '佐藤はな', height = NULL, description = '王立アカデミーの魔法の教師の一人。' WHERE character_id = 'CH004002';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327840-moAV6BeKWfuB.png', birthday = NULL, blood_type = NULL, voice_actor = '川田紳司', height = NULL, description = 'アドロフは将軍であり、騎士団の団長である。レベル60で、ユミエラが登場する前は王国で最も強い者の一人だった。' WHERE character_id = 'CH004003';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b372471-R2KUT1ngnAgz.png', birthday = NULL, blood_type = NULL, voice_actor = '貫井柚佳', height = NULL, description = 'フィルは、濃い茶色の髪が理由でいじめられている少年だ。' WHERE character_id = 'CH004004';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319862-MBg86PsoonPX.png', birthday = NULL, blood_type = NULL, voice_actor = '日高里菜', height = NULL, description = 'エレノラは、反王派に属する急進的な貴族たちの指導者であるヒルローズ公爵の娘である。彼女はエドウィン王子に片思いしており、彼の周囲の女性たちを牽制しようとしている。一見、高慢な悪女のように見えるが、実際にはただ恋に夢中な純真な少女に過ぎない。 彼女の「友人」たちは、アリシアをいじめるためのスケープゴートとして彼女を利用しているが、彼女自身は、その行動がエドウィンの目には自分を悪く見せてしまうことに気づいていない。エレノラは、リューを恐れない唯一の人物であり、彼女は彼を' WHERE character_id = 'CH004005';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b330821-Px9TEhtjlGCv.png', birthday = NULL, blood_type = NULL, voice_actor = '仲村かおり', height = NULL, description = '黒い髪を理由に娘のユミエラを疎遠にしていた母親。' WHERE character_id = 'CH004006';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b191858-VcAmTDFM9lQH.png', birthday = '2月8日', blood_type = NULL, voice_actor = '杉浦しおり', height = 128, description = 'コリスは物静かで内気な女の子で、エノルメータの最年少メンバーです。彼女には、自分にとってかけがえのない古いおもちゃがたくさんあります。彼女のテーマは『不思議の国のアリス』です。' WHERE character_id = 'CH004007';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b190374-mqGruyIYBjmo.png', birthday = '7月6日', blood_type = NULL, voice_actor = '古賀葵', height = 149, description = '彼女は、ソーシャルメディア上で魔法少女たちが自分よりも注目を集めていることに腹を立て、彼女たちを叩きのめすために「エノルメータ」のメンバーになった。当初、キウイはウテナに対して敵対的だったが、過酷な訓練を受けた後、おとなしくなり、ウテナに恋心を抱くようになった。今では、ウテナに認められることだけで満足している。 キウイは、ウテナとラブホテルに行くことをよく空想している。外見とは裏腹に、彼女は学業面でも十分に優秀で、ウテナの成績が落ちないように支えている。彼女とマグ' WHERE character_id = 'CH004008';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b175746-JlJnFu7so79j.png', birthday = '11月14日', blood_type = NULL, voice_actor = '和泉風花', height = 154, description = 'ウテナは内気で内向的な少女で、魔法少女たちに憧れを抱き、そのグッズを集め、熱心にその話題について語っている。 「トレス・マギア」への執着は、彼女自身が彼女たちと共に戦いたいと願うほどにまで達していたが、それが結局、ヴェナリータに騙される結果となってしまった。時折、彼女は少し単純なところがある。' WHERE character_id = 'CH004009';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b255889-p212OLFZ385a.png', birthday = '6月23日', blood_type = NULL, voice_actor = '津田美波', height = 151, description = '好きな食べ物：たこ焼き　一番嫌いな食べ物：しいたけ　最近嬉しかったこと：ソーシャルゲームでSSRを3枚引いたこと　ネモは皮肉屋で口が悪い女の子だ。 また、対戦相手を挑発する癖があるため、かなり傲慢なところもある。彼女はまた、マタマ・アコヤとは幼なじみだ。二人が一緒に戦うと、抜群のチームワークを発揮する。しかし、二人はよく口論もする。それにもかかわらず、お互いに恋愛感情を抱いているのかもしれない。' WHERE character_id = 'CH004010';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b255890-QaJpYLkOCpwz.png', birthday = '4月8日', blood_type = NULL, voice_actor = '相坂優歌', height = 155, description = '好きな食べ物：甘いロールオムレツ　嫌いな食べ物：コリアンダー　最近の目標：自分の歌の動画がSNSでバズること　マタマは陽気な女の子だ。 しかし、彼女はかなり自己愛が強く、批判には非常に敏感だ。彼女は「ロード・エノルメ」と『マジア・ベイザー・ウテナ』の両方を恐れており、どちらもセクハラを罰として用いる点で似ていると考えている。彼女は露出行為をしている時以外は歌がひどく下手だが、その事実はウテナに裸で歌わせられた時に明らかになった。' WHERE character_id = 'CH004011';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b288448-UwiDijgJAWVK.png', birthday = '1月27日', blood_type = NULL, voice_actor = '日笠陽子', height = NULL, description = 'ロード・エノルメは残酷で冷酷無比であり、多くの魔法少女たちの敗北や、おそらくは死さえも招いた黒幕である。 彼女は極めて傲慢で、自分こそが世界の支配者であるという強い自負心を持っており、世界はただ彼女に支配されるために存在すると信じている。彼女は自らの行いを誇りに思っており、どんな理由があっても、たとえ自分の部下であっても、躊躇なく他者を拷問する。' WHERE character_id = 'CH004012';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b301180-8vJH8ZjQuZmb.jpg', birthday = NULL, blood_type = NULL, voice_actor = '福圓美里', height = NULL, description = 'ヴェナリータは、エノルメータに魔法少女を勧誘するマスコットキャラクターである。彼は抜け目なく現実的であり、エノルメータにメンバーを勧誘するためなら、どんな手段も厭わない。 また、彼は頭の回転が速く、自分の仲間が魔法少女たちに殺されているという作り話をでっち上げ、ウテナを騙したにもかかわらず、彼女に許しを勝ち取ることができた。そして、仲間を救えるのであれば、悪者と呼ばれることなど気にしていないと語っている。' WHERE character_id = 'CH004013';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b191857-UBO6dKSU2Iin.png', birthday = '4月30日', blood_type = NULL, voice_actor = '前田佳織里', height = 156, description = 'ハルカは、非常にエネルギッシュで衝動的な少女で、いつも笑顔を絶やさず、感情のままに行動する。サヨやカオルコのことは深く気にかけており、魔法少女としての彼女たちの強さや腕前を尊敬している。しかし、彼女は極めて世間知らずで騙されやすく、知性や常識にも欠けているようだ。 それにもかかわらず、ハルカは友達を大切にする心優しい少女であり、彼女たちを守るためならどんな試練にも立ち向かう。バイザーに操られていたことを振り返ったとき、彼女は恥ずかしさと後悔を感じ、……' WHERE character_id = 'CH004014';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b301181-skLBJd1bN0Tm.png', birthday = NULL, blood_type = NULL, voice_actor = '井上喜久子', height = NULL, description = 'シスタギガントは非常に従順で、命令には文句一つ言わずに従い、罰に対しても抗議しない。また、しばしば泣いたり、ある出来事を嘆いたりしている姿が見られるほど、憂鬱な性格でもある。しかし、ロード・エノルメには文句一つ言わずに従っているものの、彼女の真の忠誠はヴェナリータに向けられている。' WHERE character_id = 'CH004015';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b191859-tmn24DMDFPIc.png', birthday = '8月17日', blood_type = NULL, voice_actor = '池田海咲', height = 146, description = '香瑠子は人前では冷静でクールなふりをしているが、実のところ、下品で口が悪く、短気な少女である。また、トレス・マジアのメンバーの中で最も聡明で狡猾でもある。彼女は争いを仕掛けることを躊躇せず、本名のままでも「マジア・サルファー」としてでも、他人を挑発したりからかったりすることを厭わない。' WHERE character_id = 'CH004016';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b301182-XGO1lQpLEXma.jpg', birthday = NULL, blood_type = NULL, voice_actor = '阿澄佳奈', height = NULL, description = 'ヴァーツは、トレス・マギアのマスコットキャラクターです。' WHERE character_id = 'CH004017';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329051-wsr4gK3EuNv1.png', birthday = NULL, blood_type = NULL, voice_actor = '丹下桜', height = NULL, description = NULL WHERE character_id = 'CH004018';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329052-gZdt7wNSJSqM.png', birthday = NULL, blood_type = NULL, voice_actor = 'ルゥティン', height = NULL, description = NULL WHERE character_id = 'CH004019';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b183417-4wWFMvcf0jpW.png', birthday = '9月1日', blood_type = NULL, voice_actor = '風間万裕子', height = 161, description = 'サヨは穏やかで落ち着きのある人物であり、その一因は彼女が神官であることに起因している。彼女が「マギア・アズール」になる決意を固めるに至った経緯を描いたフラッシュバックでも示されているように、彼女は他人を助けることを躊躇しない勇敢な人物でもある。 スキアヴォに何度も拘束され、苦しめられてきたため、サヨにはマゾヒスティックな傾向が現れ始めた。彼女のマゾヒズムとエノルメータとの「戦い」への執着は、マゼンタやサルファーが戦う機会を得ると、嫉妬さえ示すほどにまでエスカレートしている。' WHERE character_id = 'CH004020';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b204807-V4xIUWxbTWsR.png', birthday = NULL, blood_type = NULL, voice_actor = '大地葉', height = NULL, description = '長い牙と獣のような目をした、野性的で凶暴な少女。彼女の鎖骨には、魔女の呪いがバラのタトゥーとして刻まれている。ギドは現在、「魔法共鳴団」に所属している。この組織は、魔法によって、魔法のために、そして魔法そのものによって活動する団体だ。彼女のパートナーはアシャフである。' WHERE character_id = 'CH004054';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b204808-rbQTsYKvr6nE.png', birthday = NULL, blood_type = NULL, voice_actor = '森川智之', height = NULL, description = '物腰が柔らかく、繊細な顔立ちの男。背中には棺を背負い、カラスたちが群れをなして付き従っている。アシャフは現在、「魔法共鳴団」に所属している。この組織は、魔法によって、魔法のために、そして魔法そのものによって活動する団体だ。彼のパートナーはギドである。' WHERE character_id = 'CH004055';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319535-kHp3c3MkF5An.png', birthday = NULL, blood_type = NULL, voice_actor = '髙坂篤志', height = NULL, description = NULL WHERE character_id = 'CH004056';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b325561-WWCQv5MxJRLs.png', birthday = NULL, blood_type = NULL, voice_actor = '廣田行生', height = NULL, description = NULL WHERE character_id = 'CH004057';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b285315-HKDOxnboAgqi.png', birthday = NULL, blood_type = NULL, voice_actor = '日笠陽子', height = NULL, description = '町の人々から、誤って英雄であり町の守護者だと見なされている、陰謀を企む魔女。' WHERE character_id = 'CH004058';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319536-V8FyJIoslvYU.png', birthday = NULL, blood_type = NULL, voice_actor = '寺島拓篤', height = NULL, description = NULL WHERE character_id = 'CH004059';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/default.jpg', birthday = NULL, blood_type = NULL, voice_actor = '山路和弘', height = NULL, description = NULL WHERE character_id = 'CH004060';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319537-wpKTppVSW1kp.png', birthday = NULL, blood_type = NULL, voice_actor = '郷田ほづみ', height = NULL, description = 'ある都市の警察に所属する巡査部長。市内で発生したアンデッドの問題について、「魔法共鳴団」に連絡を取った。『美と死』編に登場する。' WHERE character_id = 'CH004061';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b325563-yqpz2L6q6go2.png', birthday = NULL, blood_type = NULL, voice_actor = '小林ゆう', height = NULL, description = 'ローエルは、パラディン軍団においてマット・クガットの右腕として活躍していた。' WHERE character_id = 'CH004062';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b205117-kZnDFdKPKFEc.png', birthday = NULL, blood_type = NULL, voice_actor = '逢坂良太', height = NULL, description = 'ファノラのアシスタント。' WHERE character_id = 'CH004063';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319538-2LJhQP1l5vSe.png', birthday = NULL, blood_type = NULL, voice_actor = '佐々木望', height = NULL, description = NULL WHERE character_id = 'CH004064';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b285309-cBJcnVxyL4ak.png', birthday = NULL, blood_type = NULL, voice_actor = '花澤香菜', height = NULL, description = NULL WHERE character_id = 'CH004065';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b205116-w9z5Zb0lFQI4.png', birthday = NULL, blood_type = NULL, voice_actor = '早見沙織', height = NULL, description = 'アシャフは彼女を「魔法共鳴騎士団が誇る最高のネクロマンシーの専門家」と呼んでいる。' WHERE character_id = 'CH004066';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b285312-u2xuViX8UEyu.png', birthday = NULL, blood_type = NULL, voice_actor = '石田彰', height = NULL, description = NULL WHERE character_id = 'CH004067';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b205311-qglSZDGPzJeZ.png', birthday = NULL, blood_type = NULL, voice_actor = '皆川純子', height = NULL, description = 'ヘイデン警察に所属する魔術師。同署で唯一の魔術師である彼女は、「魔女の遊び」事件の担当を務めている。' WHERE character_id = 'CH004068';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b285316-xDyRoiEgxbgz.png', birthday = NULL, blood_type = NULL, voice_actor = '富田美憂', height = NULL, description = '右頬に剣のような独特の模様、すなわち「ウルトマ」を持つ若い魔女。彼女は、世界を破壊する力を持つ「悪魔の剣アシュガン」に封印を施していた「ダウントレス・ウィッチズ」一族の17人の「オリジン」魔女の一人、クエナ・ベルベットの末裔である。 「エクゼキューショナーズ」が剣を求めて「ダウントレス・ウィッチズ」一族の隠れ家を襲撃し、一族同士が互いに殺し合う事態を招いた後、彼女は唯一の生存者となった。姉が身を挺して犠牲になったおかげで、ヘルガは剣から世界を守り続けることができたのだ。' WHERE character_id = 'CH004069';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319533-ixLLx0aKyPr1.png', birthday = NULL, blood_type = NULL, voice_actor = '芝崎典子', height = NULL, description = 'イオーネの弟子。' WHERE character_id = 'CH004070';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319534-6zULIFVCBc4d.png', birthday = NULL, blood_type = NULL, voice_actor = '木内秀信', height = NULL, description = 'ヘイデンの担当刑事であり、キーラの亡き恋人。『魔女の遊び』編で起きた連続殺人事件の犠牲者の一人。' WHERE character_id = 'CH004071';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b325560-QBsSNIQ7RcGb.png', birthday = NULL, blood_type = NULL, voice_actor = '西凜太朗', height = NULL, description = '「悪魔の剣アシュガン」は、ヴェルヴェット一族によってその真の力が封じられている、邪悪で呪われた大量破壊の剣である。一族がほぼ滅亡したあと、アシュガンはヘルガによって預けられた。' WHERE character_id = 'CH004072';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b24734-GgVZoNAPnxoc.png', birthday = '12月27日', blood_type = 'O', voice_actor = '福山潤', height = 180, description = 'ユキオは、奥村燐の双子の弟であり、藤本シロの養子である。 彼は中一級のエクソシストであり、父の勧めで7歳からエクソシストになるための修行を始め、それ以来、わずか14歳で「ドラゴン」と「ドクター」の称号を獲得し、真十字会史上最年少のエクソシストとなった。 また、ユキオは真十字会の「除霊師予備校」で薬理学を教える、同校最年少の講師でもある。生まれる前から、彼は虚弱体質で' WHERE character_id = 'CH004073';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b30429-NmVCBSzm3GNY.png', birthday = '8月20日', blood_type = 'B', voice_actor = '中井和哉', height = 181, description = '彼はリンのライバルであり、クラス一の天才だ。彼は16年前にサタンによって破壊された「呪われた神殿」の出身である。 ボンは何事も真剣に受け止め、いつかサタンを倒し（彼はこの目標をリンに盗まれたと主張している）、自らの神殿を再建できるよう、強力なエクソシストになるために全力を尽くしている。 現在、ボンは「アリア」（聖典を唱えて特定の悪魔を退治する者）と「ドラゴン」（重装の武器で戦う者）の両方で、マイスターの称号を獲得しようと奮闘している。' WHERE character_id = 'CH004074';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b24482-E6087V4uAVqL.jpg', birthday = '12月27日', blood_type = 'A', voice_actor = '岡本信彦', height = 173, description = 'この物語の主人公である15歳のリンは、人間の女性との間に生まれたサタンの息子であり、サタンの力を継承している。 その力は、誕生の瞬間にメフィスト・フェレスによって、悪魔退治の剣「クリカラ」、通称「コマケン」に封印され、それにより彼は約15年間、普通の人間としての生活を送ることができた。' WHERE character_id = 'CH004075';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b30430-LwO3yM6dg0HF.png', birthday = '3月6日', blood_type = 'B', voice_actor = '花澤香菜', height = 165, description = '花粉に少しアレルギーがある。シエミはリンの同級生であり友人だ。リンと出会う前、シエミは祖母の庭の手入れをしながら、母親がトゥルー・クロス・アカデミー内で経営する「エクソシスト専門店」を手伝っていた。 リンとユキオとの出会いの際、二人はシエミの生命力が悪魔に吸い取られていることを突き止めた。ユキオがその悪魔を祓った後、シエミはついにエクソシストになることを決意し、授業に通い始めた。その後、シエミには「テイマー」としての才能があることが明らかになった。' WHERE character_id = 'CH004076';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b38983-NrEXYWsAzm68.jpg', birthday = '7月4日', blood_type = 'O', voice_actor = '遊佐浩二', height = 176, description = 'レンゾは非常にのんきな性格だが、虫をはじめとする多くのものを恐れている。幼なじみのボンには非常に忠実だ。二人は京都でコネコマルと共に育った。また、女性に対して強い執着心を持っている。 『アリア』でマイスターになることを目指している。彼は一家の5人兄弟の末っ子であり、責任が少なくて済むからそのことを喜んでいると猫丸に話している。兄の十蔵は、兄弟の中で彼が一番の変態だと言っている。レンゾはのんきな性格で、かつては' WHERE character_id = 'CH004077';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b32162-VQiwb6CHEv8K.png', birthday = '10月11日', blood_type = 'A', voice_actor = '喜多村英梨', height = 164, description = '神木出雲は、トゥルークロス学園の「除霊予備校」でトップクラスの成績を収めている生徒であり、代々神官の家系に生まれた。' WHERE character_id = 'CH004078';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b32110-Ats6VvSZy300.png', birthday = '8月8日', blood_type = 'O', voice_actor = '佐藤利奈', height = NULL, description = '彼女は第9章で正体を明かすが、それ以前はフード付きのセーターで顔を隠し、「山田」という名前で知られていた。 現時点で漫画から得られる情報は、彼女が上級一級エクソシストであり、上級監察官であるということだけである。 彼女は、日本支部の「リスク要因」を調査するため、トゥルー・クロス・バチカン本部から派遣された。  凛が生まれる2年前、彼女は藤本シロの教え子だった。  彼女は18歳だと主張しているが、第11章でユキオは、彼女がすでに26歳になったと語っており、' WHERE character_id = 'CH004079';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b141955-uWxdyqqddQBZ.jpg', birthday = '10月10日', blood_type = NULL, voice_actor = '諏訪部順一', height = NULL, description = '騎士団の上級二等エクソシスト、トゥルー・クロス・アカデミーの「魔法陣と封印」担当1年生指導教官、そしてディープ・キープの守護者。' WHERE character_id = 'CH004080';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b30432-I4KwsegOrzfq.png', birthday = '8月28日', blood_type = NULL, voice_actor = '神谷浩史', height = 195, description = 'フェレスはトゥルー・クロス・アカデミーの理事長であり、同時にエクソシストでもある。藤本が亡くなった後、フェレスはリンを殺すよう命じられたが、リンがエクソシストになるという提案を受け入れ、彼をトゥルー・クロス・アカデミーに入学させた。 彼と、兄である「地王」アマイモンは、サタンの息子であることが強く示唆されている。彼は、ドイツ語で「3」と数え下ろすと小さな犬に変身するという、独特で奇妙な能力を持っている。その実力はまだ明らかになっていないが、彼は……' WHERE character_id = 'CH004081';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b73589-TR7obTVfLWGx.jpg', birthday = '2月24日', blood_type = 'AB', voice_actor = '関智一', height = 177, description = '彼はアークナイトであり、真の十字架騎士団のエクソシストである。' WHERE character_id = 'CH004082';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b141962-a7W9yO0aXw8O.png', birthday = NULL, blood_type = NULL, voice_actor = '西健亮', height = NULL, description = '保食（または単にウケ）は、白虎であり、神木出雲の使い魔である。かつては、彼女の母である神木玉葵に仕えていた。' WHERE character_id = 'CH004083';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b210806-ix78MMmZrbrp.png', birthday = NULL, blood_type = NULL, voice_actor = '内山昂輝', height = NULL, description = '「光の王」であり、八魔王の中で最強の存在。また、イルミナティの総司令官でもある。（出典：青の祓魔師 Wiki）' WHERE character_id = 'CH004084';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b320990-nE4x0gc10JhD.jpg', birthday = NULL, blood_type = NULL, voice_actor = '檜山修之', height = NULL, description = NULL WHERE character_id = 'CH004085';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b45001-DUT4jJDPghM8.png', birthday = NULL, blood_type = NULL, voice_actor = '井上剛', height = 163, description = 'タカラは物静かで謎めいたキャラクターだ。また、ある種の人形遣いでもある。あまり話さないが、話すときはたいてい人形遣いを通じてだ。背は低く、コネコマルよりほんの少し高い程度で、トゥルー・クロス・アカデミーの標準的な制服を着ている。 まだ目を開けている姿は描かれておらず、常にウサギの人形を手にしている。彼についてはあまり知られておらず、エクスワイヤー試験でのグループ活動にも参加しなかった。しかし、ウサギの人形を通じて話す際の声や口調は' WHERE character_id = 'CH004086';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b38984-nTBWABvnb24V.png', birthday = '1月7日', blood_type = 'A', voice_actor = '梶裕貴', height = 155, description = '三輪子猫丸は、勝呂竜士や志摩廉造と同様に京都出身であり、「真十字騎士団」のエクワイヤーであり、「エクソシスト・クラム・スクール」の生徒であり、三輪家の現当主である。' WHERE character_id = 'CH004087';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b34758-XzvetamkXXVQ.png', birthday = '12月1日', blood_type = NULL, voice_actor = '小野大輔', height = NULL, description = '新たに任命されたパラディン。グリゴリからメフィストの尋問を命じられ、証拠としてリンを捕らえた。シュラによれば、彼は外見は聖人だが、内面は悪魔だという。悪魔の剣「カリバーン」を操る。  アーサーについては、真十字軍に対して極めて忠実であること以外、現時点ではあまり知られていない。彼は上官の命令を一切疑うことなく従い、任務の妨げとなる者がいれば殺そうとするほどだ。彼は、サタンに関わるものはすべて' WHERE character_id = 'CH004088';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b43239-jnFBSkQSQ2FE.png', birthday = '5月21日', blood_type = NULL, voice_actor = '高梁碧', height = NULL, description = 'ノリコはイズモの親友だが、授業の内容が理解できず、成績も振るわなかったため、塾を辞めてしまった。' WHERE character_id = 'CH004089';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b210807-GFerzfUrZqrD.png', birthday = NULL, blood_type = NULL, voice_actor = '潘めぐみ', height = NULL, description = 'イルミナティの高位メンバーであり、ルシフェルの護衛部隊「フォスフォラス」の隊長。また、藤堂三郎太の娘でもある。' WHERE character_id = 'CH004090';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b141958-xPE2c4hKFg3t.png', birthday = NULL, blood_type = NULL, voice_actor = '井上剛', height = NULL, description = '御饌津、通称マイクは、白虎であり、同輩の中では第八位の地位にある。彼は神木出雲の使い魔であり、以前は彼女の母である神木タマモに仕えていた。' WHERE character_id = 'CH004091';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b43187-uJySWMkmaWmZ.png', birthday = NULL, blood_type = NULL, voice_actor = '高垣彩陽', height = NULL, description = '二尾の猫妖（ネコマタ）。かつては藤本の使い魔だったが、現在は凛の使い魔となっている。「クロ」は、かつて蚕の守護神として崇められていたキャット・シスである。普段は子猫の姿をしているが、意のままに巨大な姿に変身することができる。' WHERE character_id = 'CH004092';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b355269-YmQ29pBRCxdS.png', birthday = NULL, blood_type = NULL, voice_actor = '土岐隼一', height = NULL, description = '醐醍院誠は、トゥルー・クロス・アカデミーに通う生徒です。' WHERE character_id = 'CH004093';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b47527-Ms1bzAyPzCih.png', birthday = NULL, blood_type = NULL, voice_actor = '東山奈央', height = NULL, description = 'ニーちゃんは、神木出雲が2匹の狐の精霊を召喚した後、杜山しえみがデモンストレーション中に召喚した使い魔である。しえみに懐いており、よく彼女の頭の上に座っている、赤ちゃんのグリーンマンの精霊だ。 ニーちゃんは、体からアロエなどの植物を生み出したり、木の枝を伸ばしてバリアを作ったりして、シエミを助ける。遊園地での任務中、落下する破片からシエミを木のバリアで守ったことからも、ニーちゃんはシエミを大切に思っているようだ。おそらく、まだ幼いからだろう。' WHERE character_id = 'CH004094';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b196215-8jopkcHGf2fC.png', birthday = NULL, blood_type = NULL, voice_actor = '高尾奏音', height = NULL, description = '近くの集落ゾルタン出身のBランク冒険者であるリットは、ギデオンの古くからの仲間だ。 冒険者ギルドで「レッド」の話を耳にした彼女は、それが実はギデオンではないかと疑い、新しくオープンした薬局を訪れる。結局、彼女はそこで暮らし、店の手伝いをすることになる。（出典：公式サイト）' WHERE character_id = 'CH004095';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b196218-4DH68aU0IEOI.png', birthday = NULL, blood_type = NULL, voice_actor = '鈴木崚汰', height = NULL, description = '近隣の集落ゾルタン出身のDランク冒険者であるレッドは、生計を立てるためにハーブを採集・販売しており、いつか自分のハーブ店を開いて、のんびりとした生活を送ることを夢見ている。彼は、英雄たちの旅路を守り導く「ガイド」の印に恵まれており、かつてはそうしたパーティーの一員でもあった。  （出典：公式サイト）' WHERE character_id = 'CH004096';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b196217-L25DApAADCu5.png', birthday = NULL, blood_type = NULL, voice_actor = '大空直美', height = NULL, description = 'ギデオンの妹であるルティは、「英雄」の印を授かっており、魔王を討つ運命にある。これにより彼女は想像を絶する力を得たが、その一方で、英雄にとって不要であるとして、感情や人間らしさそのものが抑え込まれている。（出典：公式サイト）' WHERE character_id = 'CH004097';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319590-gDICD06CQowF.jpg', birthday = NULL, blood_type = NULL, voice_actor = '内田彩', height = NULL, description = '主人公のパーティーに傭兵として雇われた仮面の騎士。本名はエスカラタ。魔王軍の「天の王」の一人を倒した経験があることから、主人公のヴァンをサポートする役割を任されている。ヴァンのあまりにも無邪気な言動に戸惑っている。  （出典：公式サイト）' WHERE character_id = 'CH004098';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b314077-nmbj7doimSQw.jpg', birthday = NULL, blood_type = NULL, voice_actor = '柚木尚子', height = NULL, description = NULL WHERE character_id = 'CH004099';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b240579-QwyVJMe0VjeB.png', birthday = NULL, blood_type = NULL, voice_actor = '東山奈央', height = NULL, description = 'ゾルタンの冒険者ギルドの受付嬢であるメグリアは、時折、レッドが採集したハーブを買い取ってくれる。彼女は、有能で気品のあるレッドを深く信頼しており、彼が実のところ強力な騎士であることを隠しているのではないかと疑っている。（出典：公式サイト）' WHERE character_id = 'CH004100';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b206865-rWELMYSjuToS.png', birthday = NULL, blood_type = NULL, voice_actor = '天崎滉平', height = NULL, description = '近隣の集落ゾルタン出身の、稀有なBランクの冒険者であるアルベールは、「チャンピオン」の印に恵まれており、それにより大きな困難を乗り越え、驚くべき偉業を成し遂げることができる。自身の才能を自覚している彼は、その才能に見合う生き方ができているのかどうかを案じている。（出典：公式サイト）' WHERE character_id = 'CH004101';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b206862-7rxrLfcS4HfY.png', birthday = NULL, blood_type = NULL, voice_actor = NULL, height = NULL, description = '全能のデミス教会の奉仕者であり、神殿騎士団の槍術の指導者であるテオドラは、英雄のパーティーの一員であり、「クルセイダー」の印を授かっている。 彼女は冷静沈着で献身的であり、教会の教えに忠実に従っているが、心の奥底では、いつか答えを見出すであろう疑問を抱えている。（出典：公式サイト）' WHERE character_id = 'CH004102';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b204987-75fX8sdMg1gc.png', birthday = NULL, blood_type = NULL, voice_actor = '雨宮天', height = NULL, description = 'ハイエルフであり、ギデオンの戦友であり親友でもあるヤランドララは、キラミン王国で生まれ、「森の語り手」の印を授かっている。彼女は植物に助けを求めることができる。（出典：公式サイト）' WHERE character_id = 'CH004103';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b206863-BaH4o5B0zY7S.png', birthday = NULL, blood_type = NULL, voice_actor = '芹澤優', height = NULL, description = 'タンタは、ゴンゾの妹ナオとその夫ミドの息子である。レッドは彼を気に入っている。まだ自分の恵まれた境遇に気づいてはいないが、ゴンゾのように大工になりたいと願っている。彼は白目病を患っており、最終的には失明に至る恐れがある。  （出典：公式サイト）' WHERE character_id = 'CH004104';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b246068-0rNAeROBunHd.jpg', birthday = NULL, blood_type = NULL, voice_actor = '釘宮理恵', height = NULL, description = '「暗殺者」の印を持つ小柄な少女、ティッセは暗殺者ギルドの所属だ。彼女はアレスの依頼により、英雄のパーティーから追放されたギデオンの後任として加わった。彼女には「ウゲ・ウゲ」という名の小さなクモの使い魔がいる。（出典：公式サイト）' WHERE character_id = 'CH004105';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b226689-NITZXeTaV7mb.png', birthday = NULL, blood_type = NULL, voice_actor = '山中真尋', height = NULL, description = '近くの集落ゾルタンで大工として働くハーフエルフのゴンズは、レッドと親しい間柄だ。熟練の職人らしい気さくな人柄を持ち、物作りのノウハウにも長けている。隣に住む妹の家族を世話しており、その息子であるタンタを溺愛している。（出典：公式サイト）' WHERE character_id = 'CH004106';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319587-aTD3xJlOSwis.png', birthday = NULL, blood_type = NULL, voice_actor = '花守ゆみり', height = NULL, description = 'もう一人の「英雄」。彼はフラムバーグ王国の第8王子であり、故郷が魔王軍によって滅ぼされた後、生涯孤独な日々を送ることとなった。純粋で無垢な性格を持ち、強い正義感に溢れ、また深い信仰心も持っている。 彼は、あらゆる祝福や運命を、至高の神デミスの意志であると信じている。（出典：公式サイト）' WHERE character_id = 'CH004107';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b314083-JI4ks3ZOov07.png', birthday = NULL, blood_type = NULL, voice_actor = '岩澤俊樹', height = NULL, description = NULL WHERE character_id = 'CH004108';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319588-8K45rdBKRgxY.jpg', birthday = NULL, blood_type = NULL, voice_actor = '加隈亜衣', height = NULL, description = '主人公のパーティーに所属する妖精で、自らをヴァンのパートナーと名乗っている。その小さな体には、強大な魔力を秘めている。人間を嫌っているが、ヴァンだけは特別に思い、彼に恋をしてパーティーに加わった。ヴァンのすべてを認め、彼の邪魔をする者には容赦しない。  （出典：公式サイト）' WHERE character_id = 'CH004109';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b206866-ePp5EvZmJhNj.png', birthday = NULL, blood_type = NULL, voice_actor = '三宅健太', height = NULL, description = '「武術家」の印を持つ英雄のパーティの一員であるダナンは、同世代で比類なき武器の達人であり、これが魔王を倒すための最速の道だと考えてパーティに加わった。ギデオンがパーティに在籍していた頃、ダナンは彼の戦略家としての腕前を高く評価していた。（出典：公式サイト）' WHERE character_id = 'CH004110';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319589-CNr18bZqSKlz.jpg', birthday = NULL, blood_type = NULL, voice_actor = '三上哲', height = NULL, description = '聖教会の最高位にある枢機卿の一人。「英雄」の祝福を受けたヴァンの守護者となり、彼が英雄として成長できるよう様々な手を打っている。聖職者でありながら、情熱的で野心家であり、世俗的な一面も持っている。  （出典：公式サイト）' WHERE character_id = 'CH004111';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b206860-qjaMFPeTiKoa.png', birthday = NULL, blood_type = NULL, voice_actor = '徳井青空', height = NULL, description = 'ゴンゾの姉であり、タンタの母親であるナオは、明るく人当たりの良い女性で、レッドとリットが同棲を始めて以来、ずっと二人のカップリングを応援している。彼女はサウナに通い、そこでビールを飲むのが好きだが、ゼフが経営するサウナの経営がうまくいっていないのではないかと心配している。  （出典：公式サイト）' WHERE character_id = 'CH004112';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b132069-rhzpxIdCVspQ.png', birthday = NULL, blood_type = NULL, voice_actor = '内田雄馬', height = NULL, description = NULL WHERE character_id = 'CH004113';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b132070-CQlBcM1UCMSu.jpg', birthday = NULL, blood_type = NULL, voice_actor = '佐倉綾音', height = NULL, description = NULL WHERE character_id = 'CH004114';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b322663-2Ka05RD1fYK8.png', birthday = NULL, blood_type = NULL, voice_actor = '山路和弘', height = NULL, description = '阿久津のクラスの担任。薄毛を気にしている。見た目は怖くて物言いがきつい性格だが、どこか奇妙な男らしさと中年ならではの切なさを併せ持ち、生徒たちを温かく導いてくれる優しい人物だ。' WHERE character_id = 'CH004115';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b213399-SjQ9YEw8ioJ3.jpg', birthday = NULL, blood_type = NULL, voice_actor = '石原夏織', height = NULL, description = 'リリアは、リリーの悪魔退治用の武器の真の姿である。彼女はリリーの友人たちに対しては、リリーの妹を装っている。' WHERE character_id = 'CH004116';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b315430-cSBZVfYCPXia.png', birthday = NULL, blood_type = NULL, voice_actor = '梅田修一朗', height = NULL, description = '阿久津が転校して初めてできた友人。一見、人間にも動物にも無害そうな穏やかな人物に見えるが、実はかなりの戦略家であり、時折その闇の一面が垣間見える。' WHERE character_id = 'CH004117';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b213400-zaFCS64s5ivF.png', birthday = NULL, blood_type = NULL, voice_actor = '置鮎龍太郎', height = NULL, description = 'リリーの兄。' WHERE character_id = 'CH004118';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b315431-WRgREzTpmWgL.png', birthday = NULL, blood_type = NULL, voice_actor = '土岐隼一', height = NULL, description = NULL WHERE character_id = 'CH004119';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b315432-ia2l4FSLOAOM.png', birthday = NULL, blood_type = NULL, voice_actor = '東山奈央', height = NULL, description = 'ケンサクの幼なじみ（自称「彼女」）。彼女は、恋愛のライバルと見なしているリリーと激しい対立関係にある。' WHERE character_id = 'CH004120';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b315433-LLBLJ7HNgeoH.png', birthday = NULL, blood_type = NULL, voice_actor = '釘宮理恵', height = NULL, description = '悪魔界における阿久津の上司。阿久津に大きな期待を寄せ、彼を人間界へ送り出す。仕事に情熱を注ぐ「神のような上司」のように見えるが、少し常軌を逸しており、見当違いの計画を立てがちだ。無自覚なコスプレ愛好家でもある。' WHERE character_id = 'CH004121';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b321320-pHflD7OWbKmE.png', birthday = NULL, blood_type = NULL, voice_actor = '田中真弓', height = NULL, description = NULL WHERE character_id = 'CH004122';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b321321-GYftbUC4jb77.png', birthday = NULL, blood_type = NULL, voice_actor = '野沢雅子', height = NULL, description = NULL WHERE character_id = 'CH004123';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b202157-QXZO5vEbWcLk.jpg', birthday = NULL, blood_type = NULL, voice_actor = '鬼頭明里', height = NULL, description = NULL WHERE character_id = 'CH004124';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b202158-rCLSTfomAOlS.jpg', birthday = NULL, blood_type = NULL, voice_actor = '佐藤元', height = NULL, description = NULL WHERE character_id = 'CH004125';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b202156-47ytoieis5VL.jpg', birthday = NULL, blood_type = NULL, voice_actor = '上田瞳', height = NULL, description = '現王女であり、火の指輪を宿す猫族の中で最強の存在。' WHERE character_id = 'CH004126';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b202153-ANAiQD6UuYsD.jpg', birthday = NULL, blood_type = NULL, voice_actor = '小松未可子', height = NULL, description = 'アース・リングの王女。' WHERE character_id = 'CH004127';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b202154-gTwqtlgUow81.jpg', birthday = NULL, blood_type = NULL, voice_actor = '島袋美由利', height = NULL, description = '「風の指輪」を身に着けた、引きこもりのエルフの王女。' WHERE character_id = 'CH004128';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b202155-XgHhUGSRQoOA.jpg', birthday = NULL, blood_type = NULL, voice_actor = '加隈亜衣', height = NULL, description = 'サフィールは、水の国マーサの双子の王女の一人である。彼女は「リング・プリンセス」としての役割を引き受け、帝国からの影響から国を救い、姉のサフィラがマルセと結ばれることができるよう、サトに「水の指輪」を託す。そして彼女はマルセの4人目の妻となる。  彼女は強力な魔法の力を持っているが、性格は怠け者だ。' WHERE character_id = 'CH004129';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b324330-K6d1RAvGQom4.jpg', birthday = NULL, blood_type = NULL, voice_actor = '千葉繁', height = NULL, description = 'アラバスタ、大賢者。サトとヒメからは「おじいちゃん」と呼ばれている。ヒメと「光の指輪」を守るため、彼女を連れて地球へのポータルを開くことができた。リングキング、アビス、魔法、そして世界について非常に詳しい。    若き日のある時期、スマラグディと関わりがあり、二人は愛し合っていた。彼女はエルフであるため、彼よりもはるかに長生きすることになるため、彼が年老いていく姿を見る苦痛を彼女に味わわせないよう、彼は去っていった。' WHERE character_id = 'CH004130';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b331021-9CesPTMTTtye.png', birthday = NULL, blood_type = NULL, voice_actor = '富田美憂', height = NULL, description = 'ヒメの妹。' WHERE character_id = 'CH004131';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b136977-xjr9aml0CrIb.png', birthday = '3月19日', blood_type = NULL, voice_actor = '金元寿子', height = NULL, description = '葵は友崎の同級生であり、格闘ゲーム『タックファム』のランキング2位のプレイヤーだ。彼女は努力家なため、何事にも秀でており、そのあまりの完璧さから、多くの人々からは「まさに完璧」と見なされている。 多くの人にとって、彼女はのんきで気楽な学生のように見える。しかし、友崎は、彼女が実は非常に真面目で、思いやりがあり、人を支える一方で、どこか厳しく、無愛想な人物であることを知ることになる。' WHERE character_id = 'CH004132';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b136978-aF9vqp3LdMeV.png', birthday = NULL, blood_type = NULL, voice_actor = '佐藤元', height = NULL, description = '友崎文也は、友達が一人もおらず、学校ではアウトサイダー扱いされている高校生だ。孤独な日常から逃れるため、彼は『アタックファミリー』（通称「タックファム」）という格闘ゲームに没頭し、その熱心さゆえに「nanashi」というユーザー名で日本ランキング1位に輝いている。   友崎は、自分自身を人生における「最下位キャラ」――生まれつき不運で、孤独な運命を背負った存在――だと考えている。しかし、オンライン上のライバルである日南葵と出会った後、彼女から学ぶことに同意し、' WHERE character_id = 'CH004133';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b136979-KZW38ANA8Xsc.png', birthday = NULL, blood_type = NULL, voice_actor = '茅野愛衣', height = NULL, description = 'フカは、フミヤの同級生で、物静かで本好きの少女。よく図書館で時間を過ごしている。小説家志望である彼女は、人々の行動の動機や、現在の自分を作り上げた経験について、あれこれと推測したり研究したりするのが大好きだ。彼女のお気に入りの作家はマイケル・アンディである。' WHERE character_id = 'CH004134';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b189228-E9dLB4OlvzN0.png', birthday = NULL, blood_type = NULL, voice_actor = '水野駿太郎', height = NULL, description = NULL WHERE character_id = 'CH004135';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327757-vAKUaZe2whUk.png', birthday = NULL, blood_type = NULL, voice_actor = '内山夕実', height = NULL, description = NULL WHERE character_id = 'CH004136';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b161225-oqLeLiVn2YWJ.png', birthday = NULL, blood_type = NULL, voice_actor = '金子彩花', height = NULL, description = NULL WHERE character_id = 'CH004137';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327797-Sm1a408ScSOv.png', birthday = NULL, blood_type = NULL, voice_actor = '平塚紗依', height = NULL, description = NULL WHERE character_id = 'CH004138';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b136976-y5omCGUoeQsO.png', birthday = NULL, blood_type = NULL, voice_actor = '長谷川育美', height = 162, description = '彼女は、日南葵と同じ陸上部所属の友崎文也の、元気でいたずら好き、そして人気のある同級生である。 夏林花火とは親しい友人関係にある。表向きは明るい態度を保っているが、実は自分自身や自分の性格に自信がなく、雰囲気を壊さないよう、つい流されがちだ。また、孤独な花火にしつこく付きまとい、友達になってもらおうとするなど、自分の目的を達成するためにはかなり粘り強い面もある。' WHERE character_id = 'CH004139';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327753-ao6cyDY7oFm0.png', birthday = NULL, blood_type = NULL, voice_actor = '日岡なつみ', height = NULL, description = 'ミカはマオの友人であり、エリカのグループの一員だ。' WHERE character_id = 'CH004140';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327803-Nx61xLhdQUOC.png', birthday = NULL, blood_type = NULL, voice_actor = '川井田夏海', height = NULL, description = NULL WHERE character_id = 'CH004141';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327755-cDjhV5piHzg7.png', birthday = NULL, blood_type = NULL, voice_actor = '竹田海渡', height = NULL, description = NULL WHERE character_id = 'CH004142';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327804-g7EMTDDLGwAz.png', birthday = NULL, blood_type = NULL, voice_actor = '広瀬ゆうき', height = NULL, description = NULL WHERE character_id = 'CH004143';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b161223-FiQcwSeIzncf.png', birthday = NULL, blood_type = NULL, voice_actor = '前川涼子', height = NULL, description = '花火は、友崎文也の率直で人付き合いが苦手な同級生だ。彼女は、自分とは正反対の性格を持つミミミと親しい間柄にある。その率直な性格のせいで、しばしば周囲から嫌われてしまう。ある時、エリカの嫌がらせやいじめの行為を公然と非難したことでトラブルに巻き込まれ、結果として自分自身がいじめの標的となってしまった。' WHERE character_id = 'CH004144';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327756-IVIZYlSDIBAb.png', birthday = NULL, blood_type = NULL, voice_actor = '日高里菜', height = NULL, description = '兄に対して頻繁に嫌悪感を露わにする友崎の妹。' WHERE character_id = 'CH004145';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327802-wO16iZqoHEtm.png', birthday = NULL, blood_type = NULL, voice_actor = '和久野愛佳', height = NULL, description = NULL WHERE character_id = 'CH004146';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b161222-N4sFa1qUg5C6.png', birthday = NULL, blood_type = NULL, voice_actor = '稗田寧々', height = NULL, description = '対立を嫌う性格のため、エリカの理不尽な行動に対して、しばしば立ち向かうことをためらってしまう。修司に恋をしている彼女は、彼の練習相手になるために「タックファム」の遊び方を学ぶことにした。その結果、フミヤに「タックファム」の指導を頼むことになり、それがきっかけで二人は友人関係になる。' WHERE character_id = 'CH004147';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327758-XfsnahSysFx6.png', birthday = NULL, blood_type = NULL, voice_actor = '大塚剛央', height = NULL, description = NULL WHERE character_id = 'CH004148';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327801-VcsskM3MFaqo.png', birthday = NULL, blood_type = NULL, voice_actor = '那谷柊優', height = NULL, description = NULL WHERE character_id = 'CH004149';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b161226-XxYqYDTZSq6P.png', birthday = '7月27日', blood_type = NULL, voice_actor = '岡本信彦', height = NULL, description = '修司は、友崎文也の同級生で、自分のグループの「アルファ」であり、事実上のリーダーと見なされている横暴な人物である。 修司は負けず嫌いで、負けた時には些細なことにこだわってしまう。例えば、『タッカファム』で文也に敗れた際、その敗北を「運が悪かっただけ」と片付けつつ、リベンジマッチで勝つために懸命に練習に励んだことからも、その性格がうかがえる。 その性格にもかかわらず、彼は理性的で、自分なりの結論を導き出すことができる人物としても知られている。例えば、文也の努力を認めた後、最終的に彼を自分のグループの一員として受け入れたことなどが挙げられる。' WHERE character_id = 'CH004150';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b161224-nBXW92omz0Kg.png', birthday = NULL, blood_type = NULL, voice_actor = '藤田茜', height = NULL, description = NULL WHERE character_id = 'CH004151';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327800-8Wnuw1Weyhxj.png', birthday = NULL, blood_type = NULL, voice_actor = '大空直美', height = NULL, description = NULL WHERE character_id = 'CH004152';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b185536-IexptfwyKbDj.png', birthday = NULL, blood_type = NULL, voice_actor = '島﨑信長', height = NULL, description = '彼は、友崎文也の同級生で、中村修二のグループに属する、人気者で社交的、そしてイケメンな人物であり、グループの中で最も頭が良くて冷静なメンバーだとよく見なされている。 タカヒロは普段から女子の注目を集めており、非常に口がうまい。文也は彼の話し方を手本にしているほどだ。また、彼は文也を取り巻く変化、特に文也が意図的に態度を変えていることにも気づくほど洞察力に富んでいる。彼は生まれつき' WHERE character_id = 'CH004153';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327754-eHwYUKl28PvZ.png', birthday = NULL, blood_type = NULL, voice_actor = '市ノ瀬加那', height = NULL, description = 'マオはミカの友人であり、エリカのグループの一員だ。' WHERE character_id = 'CH004154';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327799-il36f2k9ciFY.png', birthday = NULL, blood_type = NULL, voice_actor = '黒崎しおり', height = NULL, description = NULL WHERE character_id = 'CH004155';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b294130-Fih0fWIZgr1B.png', birthday = NULL, blood_type = NULL, voice_actor = '田村睦心', height = NULL, description = 'めったに見かけることのない珍しいスライム。正式な名称はなく、「最弱のスライム」や「もろいスライム」など、さまざまな呼び名で知られている。   モンスター図鑑によると、「ほんの少し突かれたり、強い突風にさらされたりしただけで、存在そのものが消えてしまうほど脆弱」だと言われている。アイビーと友達になり、二人は一緒に旅に出る。青いポーションを、瓶ごと飲み干してしまう。' WHERE character_id = 'CH004156';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b294131-26YBlQuNlcOe.png', birthday = NULL, blood_type = NULL, voice_actor = '鈴木愛奈', height = NULL, description = 'すべての人々が神からスキルを与えられるこの世界で、彼女は「テイマー」のスキルを与えられた若い少女だ。しかし、彼女のランクは最下位の「スターレス」である。 「星なき者」は不吉な存在と見なされるため、彼女は家族に見捨てられ、村から追い出されてしまった。実のところ、アイビーは異世界から転生してきたのだ。時折、前世の記憶が彼女に助言をくれることもあるが、それらはほとんど役に立たない。' WHERE character_id = 'CH004157';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323657-KilBgUIRynlx.png', birthday = NULL, blood_type = NULL, voice_actor = '千葉進歩', height = NULL, description = NULL WHERE character_id = 'CH004158';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323666-xOzyyUjy9kXC.png', birthday = NULL, blood_type = NULL, voice_actor = '土岐隼一', height = NULL, description = '冒険者グループ「ヴェルダント・ウィンド」の一員。ミーラの兄であり、トルトの双子の兄弟で、顔立ち、声、性格が似ている。両手剣の2つ星スキルと、水属性攻撃の1つ星スキルを持っている。   甘いものが大好きだ。' WHERE character_id = 'CH004159';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329628-f4GQ1XDKh3WL.png', birthday = NULL, blood_type = NULL, voice_actor = '山本兼平 ', height = NULL, description = NULL WHERE character_id = 'CH004160';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329654-lzHO5HgrPcQX.png', birthday = NULL, blood_type = NULL, voice_actor = '稲田徹', height = NULL, description = NULL WHERE character_id = 'CH004161';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323658-hKFJqvjD4Byk.png', birthday = NULL, blood_type = NULL, voice_actor = '間宮康弘', height = NULL, description = NULL WHERE character_id = 'CH004162';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329620-LcT59lPQzwum.png', birthday = NULL, blood_type = NULL, voice_actor = '松本大', height = NULL, description = NULL WHERE character_id = 'CH004163';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329629-aWURcDVlTNoQ.png', birthday = NULL, blood_type = NULL, voice_actor = '豊口めぐみ', height = NULL, description = NULL WHERE character_id = 'CH004164';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329655-AGaZInSXey4F.png', birthday = NULL, blood_type = NULL, voice_actor = '前野智昭', height = NULL, description = NULL WHERE character_id = 'CH004165';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323649-x8dZmPhNREKx.png', birthday = NULL, blood_type = NULL, voice_actor = '麦穂あんな', height = NULL, description = 'アダンドラは、ブラックパンサーに似た高ランクのモンスターである。その獰猛さは極めて激しく、森で遭遇すれば死を免れないと言われ、たった1体を倒すだけでも、高ランクの冒険者たちによる複数のパーティが力を合わせなければならないほどである。' WHERE character_id = 'CH004166';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323659-uABwn7l9th0i.png', birthday = NULL, blood_type = NULL, voice_actor = '杉田智和', height = NULL, description = '精鋭冒険者グループ「サンダーキング」のリーダー。冒険者の中でもトップクラスの存在であり、その実力は「モンスター殲滅隊」の隊長を務めるほどである。 頼りになる人物だが、仲間たちの前では時折、少しぼんやりとした一面を見せることもある。レベル2の「魔法耐性」スキルとレベル3の「ロングソード」スキルを持っている。アイビーには優しく接している。' WHERE character_id = 'CH004167';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329630-3R6SabmkDBRI.png', birthday = NULL, blood_type = NULL, voice_actor = '斎藤楓子', height = NULL, description = NULL WHERE character_id = 'CH004168';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329656-3HfJdjj1yjQy.png', birthday = NULL, blood_type = NULL, voice_actor = '浪川大輔', height = NULL, description = NULL WHERE character_id = 'CH004169';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323652-Y4FKwHpSDqk2.png', birthday = NULL, blood_type = NULL, voice_actor = '平野文', height = NULL, description = 'ラトミ村の占い師。「一ツ星」の予知能力を持つ。村にとって、特産品であるザロの最適な収穫時期を占う、かけがえのない存在である。' WHERE character_id = 'CH004170';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323660-wcseqZ3ljHwH.png', birthday = NULL, blood_type = NULL, voice_actor = '安元洋貴', height = NULL, description = '精鋭冒険者グループ「サンダー・キング」の一員。 かわいいものが好きで、特にソラに目をつけている。人の顔を覚えるのが得意だ。スキルには、徒手格闘（ランク2）、水魔法（ランク2）、片手剣（ランク2）がある。アイビーには優しく接している。' WHERE character_id = 'CH004171';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329631-8wTArte5FDPu.png', birthday = NULL, blood_type = NULL, voice_actor = '劉セイラ', height = NULL, description = NULL WHERE character_id = 'CH004172';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329639-sknhg3kFWxbK.png', birthday = NULL, blood_type = NULL, voice_actor = '中島ヨシキ', height = NULL, description = NULL WHERE character_id = 'CH004173';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329657-AJGmaqRRd2zZ.png', birthday = NULL, blood_type = NULL, voice_actor = '森川智之', height = NULL, description = NULL WHERE character_id = 'CH004174';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323653-Pwdfg4iSdpEJ.png', birthday = NULL, blood_type = NULL, voice_actor = '三宅健太', height = NULL, description = 'ラトメ村自警団の団長。彼と彼の部隊は、村の門の警備やパトロールなどの任務を交代で担当している。思いやりがあり、活発な性格で、自分が正しいと信じたことはすぐに実行に移す「行動派」である。 しかし、彼はつい熱中しすぎてしまい、時にはやりすぎてトラブルを引き起こすこともあるため、副隊長のヴェリヴェラから頻繁に注意を受けている。彼はアイビーに強く惹かれており、いつも彼女をじっと見つめている。' WHERE character_id = 'CH004175';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323661-ZRNx3m4XsSls.png', birthday = NULL, blood_type = NULL, voice_actor = '勝杏里', height = NULL, description = NULL WHERE character_id = 'CH004176';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329641-lMe9ubcXlIVq.png', birthday = NULL, blood_type = NULL, voice_actor = '高橋伸也', height = NULL, description = NULL WHERE character_id = 'CH004177';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329658-aa6k8ZGAh0AX.png', birthday = NULL, blood_type = NULL, voice_actor = '綿貫竜之介', height = NULL, description = NULL WHERE character_id = 'CH004178';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323654-cGgIKLUHobWv.png', birthday = NULL, blood_type = NULL, voice_actor = '鳥海浩輔', height = NULL, description = 'ラトメ村自警団の一員。副団長として、オグト団長を補佐している。衝動的なオグト団長の気まぐれに常に振り回される、苦労の絶えない男であり、団長をなだめたり、その残した後始末に追われたりして、いつも慌ただしく動き回っている。 普段は冷静だが、怒ると恐ろしいほどだと噂されている。実際、ヴェリヴェラが本気で激怒すると、オグト隊長でさえも怯えてしまうほどだ。彼はアイビーに優しく接している。' WHERE character_id = 'CH004179';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323662-lnNjPIu2WB1S.png', birthday = NULL, blood_type = NULL, voice_actor = '中井和哉', height = NULL, description = NULL WHERE character_id = 'CH004180';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329659-vmKCEzYHb4kR.png', birthday = NULL, blood_type = NULL, voice_actor = '木村隼人', height = NULL, description = NULL WHERE character_id = 'CH004181';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323655-vHZlnM7yjQNv.png', birthday = NULL, blood_type = NULL, voice_actor = 'てらそままさき', height = NULL, description = '精鋭冒険者グループ「炎の剣」のリーダー。威圧的な外見とは裏腹に、心根は優しい。手ごわい戦士であるだけでなく、鋭い知性も兼ね備えており、メンバーとの相互信頼のもとでグループを率いている。まさにその名にふさわしいリーダーである。 彼のスキルには、白兵戦（ランク3）、剣術（ランク2）、耐久力（ランク1）がある。彼はアイビーに優しく接している。' WHERE character_id = 'CH004182';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323663-R8pd9jlUf3Rb.png', birthday = NULL, blood_type = NULL, voice_actor = '井上麻里奈', height = NULL, description = '冒険者グループ「ヴェルダント・ウィンド」の一員。美しく、大人びた風貌の女性だが、少々不器用なところがある。2つ星のテイマーであり、ルスタルとリーデルという2体のレアなスライムを従えている。お菓子が大好きで、アイビーに優しく接している。' WHERE character_id = 'CH004183';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329660-1Ua8zwycTAxK.png', birthday = NULL, blood_type = NULL, voice_actor = '上田燿司', height = NULL, description = NULL WHERE character_id = 'CH004184';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323656-dRE7fvcaFHJ5.png', birthday = NULL, blood_type = NULL, voice_actor = '八代拓', height = NULL, description = '精鋭冒険者グループ「ソード・オブ・フレイム」の一員。陽気で人柄が良く、仲間、特に妹のように慕っているアイビーの世話をしっかりしてくれる。甘いものが大好きだ。 しかし、料理の腕は最悪で、食事当番が回ってくるたびに、彼自身も他のメンバーもがっかりさせられてしまう。3つ星の「炎の攻撃」スキルと、2つ星の「ロングソード」スキルを持っている。 アイビーには優しく接している。' WHERE character_id = 'CH004185';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323665-TgIBap4UqdEB.png', birthday = NULL, blood_type = NULL, voice_actor = '土岐隼一', height = NULL, description = '冒険者グループ「ヴェルダント・ウィンド」の一員。ミーラの兄であり、マルマの双子の兄弟で、顔立ち、声、性格が似ている。2つ星の「防御」スキルと1つ星の「ロングソード」スキルを持っている。お菓子が大好きだ。' WHERE character_id = 'CH004186';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b298248-P733qcY9hZSi.png', birthday = NULL, blood_type = NULL, voice_actor = '梶裕貴', height = NULL, description = '異世界からやってきた、無敵の剣の達人。剣術の腕前に加え、超人的な直感力を備えており、目の前に現れた敵を殺すための最善の方法を、一瞥するだけで見抜くことができる。' WHERE character_id = 'CH004187';
